// mastermind4_4_8.pl: a ProbLog program written in WebPPL by tddlog's
// scripts/problog2ppl.py, first order as it is written. A relation is an
// object from a tuple's key to {t: the tuple, v: whether it holds}, v a
// function of no arguments that says whether the tuple holds in the world
// being enumerated, memoized within it; each probabilistic fact is a coin of
// its own (`flip`), drawn where a world first reads it; a rule's instances
// are maps over the relations its body joins. The facts are lpFacts, which
// the runner reads from the facts file: {relation: [[argument ...,
// probability], ...]}. The queries are enumerated exactly, given the
// evidence.

var yes = function() { return true; };
var no = function() { return false; };
// a coin of probability p, drawn once in a world
var coin = function(p) { return mem(function() { return flip(p); }); };
var and = function(xs) { return function() { return all(function(x) { return x(); }, xs); }; };
var not = function(x) { return function() { return !x(); }; };
var keyOf = function(t) { return JSON.stringify(t); };
// whether the tuple t of r holds
var holds = function(r, t) { var e = r[keyOf(t)]; return e ? e.v : no; };
// the entry of t, if it is a tuple of r: none or one to map over
var probe = function(r, t) { var e = r[keyOf(t)]; return e ? [e] : []; };
// the entries of r by their values at positions ps (from 0)
var index = function(r, ps) {
  return _.groupBy(map(function(e) { return {k: keyOf(_.at(e.t, ps)), t: e.t, v: e.v}; }, _.values(r)), 'k');
};
// whether a tuple of the index's key k holds
var holdsAny = function(ix, k) {
  var es = ix[keyOf(k)] || [];
  return function() { return any(function(e) { return e.v(); }, es); };
};
// the choice of an annotated disjunction p1::h1; ...; pn::hn: whether each
// head is the one chosen, the k-th with probability pk and none with the rest
var choose = function(ps) {
  var rest = 1 - sum(ps);
  var vs = _.range(ps.length + (rest > 0 ? 1 : 0));
  var c = mem(function() { return categorical({ps: rest > 0 ? ps.concat([rest]) : ps, vs: vs}); });
  return map(function(k) { return function() { return c() === k; }; }, _.range(ps.length));
};
// the instances, [relation, tuple, holding] each, of relation `name`
var only = function(name, instances) { return filter(function(i) { return i[0] === name; }, instances); };
// the relation of base and instances: a tuple holds where its fact or one
// of its instances does
var relation = function(base, instances) {
  var entries = map(function(e) { return {k: keyOf(e.t), t: e.t, v: e.v}; }, _.values(base)).concat(
    map(function(i) { return {k: keyOf(i[1]), t: i[1], v: i[2]}; }, instances));
  return mapObject(function(k, es) {
    var vs = map(function(e) { return e.v; }, es);
    return {t: es[0].t, v: mem(function() { return any(function(x) { return x(); }, vs); })};
  }, _.groupBy(entries, 'k'));
};
// a relation of facts, [argument ..., probability] each
var relationOfFacts = function(rows) {
  return _.fromPairs(map(function(row) {
    var t = row.slice(0, row.length - 1), p = row[row.length - 1];
    return [keyOf(t), {t: t, v: p >= 1 ? yes : coin(p)}];
  }, rows));
};

var peg_facts = relationOfFacts(lpFacts['peg/2'] || []);
var colour_facts = relationOfFacts(lpFacts['colour/2'] || []);
var round_facts = relationOfFacts(lpFacts['round/1'] || []);
var guess_facts = relationOfFacts(lpFacts['guess/3'] || []);
var guessed_facts = relationOfFacts(lpFacts['guessed/3'] || []);

var instances_code = [].concat(
  // 0.25::code(1,c0); 0.25::code(1,c1); 0.25::code(1,c2); 0.25::code(1,c3).
  (function() {
    var chosen = choose([0.25, 0.25, 0.25, 0.25]);
    return [
      ['code', [1, 'c0'], chosen[0]],
      ['code', [1, 'c1'], chosen[1]],
      ['code', [1, 'c2'], chosen[2]],
      ['code', [1, 'c3'], chosen[3]]
    ];
  })(),
  // 0.25::code(2,c0); 0.25::code(2,c1); 0.25::code(2,c2); 0.25::code(2,c3).
  (function() {
    var chosen = choose([0.25, 0.25, 0.25, 0.25]);
    return [
      ['code', [2, 'c0'], chosen[0]],
      ['code', [2, 'c1'], chosen[1]],
      ['code', [2, 'c2'], chosen[2]],
      ['code', [2, 'c3'], chosen[3]]
    ];
  })(),
  // 0.25::code(3,c0); 0.25::code(3,c1); 0.25::code(3,c2); 0.25::code(3,c3).
  (function() {
    var chosen = choose([0.25, 0.25, 0.25, 0.25]);
    return [
      ['code', [3, 'c0'], chosen[0]],
      ['code', [3, 'c1'], chosen[1]],
      ['code', [3, 'c2'], chosen[2]],
      ['code', [3, 'c3'], chosen[3]]
    ];
  })(),
  // 0.25::code(4,c0); 0.25::code(4,c1); 0.25::code(4,c2); 0.25::code(4,c3).
  (function() {
    var chosen = choose([0.25, 0.25, 0.25, 0.25]);
    return [
      ['code', [4, 'c0'], chosen[0]],
      ['code', [4, 'c1'], chosen[1]],
      ['code', [4, 'c2'], chosen[2]],
      ['code', [4, 'c3'], chosen[3]]
    ];
  })()
);
var code = relation({}, instances_code);

var guess = guess_facts;

var peg = peg_facts;

var round = round_facts;

var guess_by_1_2 = index(guess, [0, 1]);
var code_by_1 = index(code, [0]);
// black/3: recursive; the rules applied in stages from no tuple, each
// reading the stage before, until a stage adds no tuple and the stages number the tuples
var stage_black = function(rels) {
  var black = rels[0];
  var black_by_2 = index(black, [1]);
  var instances_black = [].concat(
    // black(G,0,0) :- round(G).
    (function() {
      return _.flatten(map(function(e1) {
        var G = e1.t[0];
        return [['black', [G, 0, 0], e1.v]];
      }, _.values(round)));
    })(),
    // black(G,K,B) :- peg(J,K), black(G,J,B0), guess(G,K,X), code(K,X), B is B0 + 1.
    (function() {
      return _.flatten(map(function(e1) {
        var J = e1.t[0];
        var K = e1.t[1];
        return _.flatten(map(function(e2) {
          var G = e2.t[0];
          var B0 = e2.t[2];
          var B = (B0 + 1);
          return _.flatten(map(function(e3) {
            var X = e3.t[2];
            return _.flatten(map(function(e4) {
              return [['black', [G, K, B], and([e1.v, e2.v, e3.v, e4.v])]];
            }, probe(code, [K, X])));
          }, (guess_by_1_2[keyOf([G, K])] || [])));
        }, (black_by_2[keyOf([J])] || [])));
      }, _.values(peg)));
    })(),
    // black(G,K,B) :- peg(J,K), black(G,J,B), guess(G,K,X), code(K,Y), X \= Y.
    (function() {
      return _.flatten(map(function(e1) {
        var J = e1.t[0];
        var K = e1.t[1];
        return _.flatten(map(function(e2) {
          var G = e2.t[0];
          var B = e2.t[2];
          return _.flatten(map(function(e3) {
            var X = e3.t[2];
            return _.flatten(map(function(e4) {
              var Y = e4.t[1];
              if (X !== Y) {
                return [['black', [G, K, B], and([e1.v, e2.v, e3.v, e4.v])]];
              } else {
                return [];
              }
            }, (code_by_1[keyOf([K])] || [])));
          }, (guess_by_1_2[keyOf([G, K])] || [])));
        }, (black_by_2[keyOf([J])] || [])));
      }, _.values(peg)));
    })()
  );
  var next_black = relation({}, instances_black);
  return [next_black];
};
var stages_black = function(rels, stage, before) {
  var size = sum(map(function(r) { return _.size(r); }, rels));
  return stage < size || size !== before ? stages_black(stage_black(rels), stage + 1, size) : rels;
};
var rels_black = stages_black([{}], 0, -1);
var black = rels_black[0];

var colour = colour_facts;

// count/3: recursive; the rules applied in stages from no tuple, each
// reading the stage before, until a stage adds no tuple and the stages number the tuples
var stage_count = function(rels) {
  var count = rels[0];
  var count_by_2 = index(count, [1]);
  var instances_count = [].concat(
    // count(X,0,0) :- colour(_,X).
    (function() {
      return _.flatten(map(function(e1) {
        var X = e1.t[1];
        return [['count', [X, 0, 0], e1.v]];
      }, _.values(colour)));
    })(),
    // count(X,K,N) :- peg(J,K), count(X,J,N0), code(K,X), N is N0 + 1.
    (function() {
      return _.flatten(map(function(e1) {
        var J = e1.t[0];
        var K = e1.t[1];
        return _.flatten(map(function(e2) {
          var X = e2.t[0];
          var N0 = e2.t[2];
          var N = (N0 + 1);
          return _.flatten(map(function(e3) {
            return [['count', [X, K, N], and([e1.v, e2.v, e3.v])]];
          }, probe(code, [K, X])));
        }, (count_by_2[keyOf([J])] || [])));
      }, _.values(peg)));
    })(),
    // count(X,K,N) :- peg(J,K), count(X,J,N), code(K,Y), X \= Y.
    (function() {
      return _.flatten(map(function(e1) {
        var J = e1.t[0];
        var K = e1.t[1];
        return _.flatten(map(function(e2) {
          var X = e2.t[0];
          var N = e2.t[2];
          return _.flatten(map(function(e3) {
            var Y = e3.t[1];
            if (X !== Y) {
              return [['count', [X, K, N], and([e1.v, e2.v, e3.v])]];
            } else {
              return [];
            }
          }, (code_by_1[keyOf([K])] || [])));
        }, (count_by_2[keyOf([J])] || [])));
      }, _.values(peg)));
    })()
  );
  var next_count = relation({}, instances_count);
  return [next_count];
};
var stages_count = function(rels, stage, before) {
  var size = sum(map(function(r) { return _.size(r); }, rels));
  return stage < size || size !== before ? stages_count(stage_count(rels), stage + 1, size) : rels;
};
var rels_count = stages_count([{}], 0, -1);
var count = rels_count[0];

var guessed = guessed_facts;

var count_by_1_2 = index(count, [0, 1]);
var instances_common = [].concat(
  // common(G,X,N) :- guessed(G,X,M), count(X,4,N), N =< M.
  (function() {
    return _.flatten(map(function(e1) {
      var G = e1.t[0];
      var X = e1.t[1];
      var M = e1.t[2];
      return _.flatten(map(function(e2) {
        var N = e2.t[2];
        if (N <= M) {
          return [['common', [G, X, N], and([e1.v, e2.v])]];
        } else {
          return [];
        }
      }, (count_by_1_2[keyOf([X, 4])] || [])));
    }, _.values(guessed)));
  })(),
