  (function() {
    return _.flatten(map(function(e1) {
      var G = e1.t[0];
      var X = e1.t[1];
      var M = e1.t[2];
      return _.flatten(map(function(e2) {
        var N = e2.t[2];
        if (N > M) {
          return [['common', [G, X, M], and([e1.v, e2.v])]];
        } else {
          return [];
        }
      }, (count_by_1_2[keyOf([X, 4])] || [])));
    }, _.values(guessed)));
  })()
);
var common = relation({}, instances_common);

var common_by_1_2 = index(common, [0, 1]);
// matched/3: recursive; the rules applied in stages from no tuple, each
// reading the stage before, until a stage adds no tuple and the stages number the tuples
var stage_matched = function(rels) {
  var matched = rels[0];
  var matched_by_2 = index(matched, [1]);
  var instances_matched = [].concat(
    // matched(G,0,0) :- round(G).
    (function() {
      return _.flatten(map(function(e1) {
        var G = e1.t[0];
        return [['matched', [G, 0, 0], e1.v]];
      }, _.values(round)));
    })(),
    // matched(G,I,T) :- colour(J,X), I is J + 1, matched(G,J,T0), common(G,X,M), T is T0 + M.
    (function() {
      return _.flatten(map(function(e1) {
        var J = e1.t[0];
        var X = e1.t[1];
        var I = (J + 1);
        return _.flatten(map(function(e2) {
          var G = e2.t[0];
          var T0 = e2.t[2];
          return _.flatten(map(function(e3) {
            var M = e3.t[2];
            var T = (T0 + M);
            return [['matched', [G, I, T], and([e1.v, e2.v, e3.v])]];
          }, (common_by_1_2[keyOf([G, X])] || [])));
        }, (matched_by_2[keyOf([J])] || [])));
      }, _.values(colour)));
    })()
  );
  var next_matched = relation({}, instances_matched);
  return [next_matched];
};
var stages_matched = function(rels, stage, before) {
  var size = sum(map(function(r) { return _.size(r); }, rels));
  return stage < size || size !== before ? stages_matched(stage_matched(rels), stage + 1, size) : rels;
};
var rels_matched = stages_matched([{}], 0, -1);
var matched = rels_matched[0];

var matched_by_2 = index(matched, [1]);
var black_by_1_2 = index(black, [0, 1]);
var instances_white = [].concat(
  // white(G,W) :- matched(G,4,T), black(G,4,B), W is T - B.
  (function() {
    return _.flatten(map(function(e1) {
      var G = e1.t[0];
      var T = e1.t[2];
      return _.flatten(map(function(e2) {
        var B = e2.t[2];
        var W = (T - B);
        return [['white', [G, W], and([e1.v, e2.v])]];
      }, (black_by_1_2[keyOf([G, 4])] || [])));
    }, (matched_by_2[keyOf([4])] || [])));
  })()
);
var white = relation({}, instances_white);

// component 0 bool
// component 1 bool
// component 2 bool
// component 3 bool
// component 4 bool
// component 5 bool
// component 6 bool
// component 7 bool
// component 8 bool
// component 9 bool
// component 10 bool
// component 11 bool
// component 12 bool
// component 13 bool
// component 14 bool
// component 15 bool
var model = function() {
  condition(holds(black, ['g0', 4, 0])());
  condition(holds(white, ['g0', 0])());
  condition(holds(black, ['g1', 4, 3])());
  condition(holds(white, ['g1', 0])());
  condition(holds(black, ['g2', 4, 0])());
  condition(holds(white, ['g2', 1])());
  condition(holds(black, ['g3', 4, 0])());
  condition(holds(white, ['g3', 3])());
  condition(holds(black, ['g4', 4, 2])());
  condition(holds(white, ['g4', 0])());
  condition(holds(black, ['g5', 4, 1])());
  condition(holds(white, ['g5', 1])());
  condition(holds(black, ['g6', 4, 1])());
  condition(holds(white, ['g6', 0])());
  condition(holds(black, ['g7', 4, 0])());
  condition(holds(white, ['g7', 2])());
  return [holds(code, [1, 'c0'])(),
          holds(code, [1, 'c1'])(),
          holds(code, [1, 'c2'])(),
          holds(code, [1, 'c3'])(),
          holds(code, [2, 'c0'])(),
          holds(code, [2, 'c1'])(),
          holds(code, [2, 'c2'])(),
          holds(code, [2, 'c3'])(),
          holds(code, [3, 'c0'])(),
          holds(code, [3, 'c1'])(),
          holds(code, [3, 'c2'])(),
          holds(code, [3, 'c3'])(),
          holds(code, [4, 'c0'])(),
          holds(code, [4, 'c1'])(),
          holds(code, [4, 'c2'])(),
          holds(code, [4, 'c3'])()];
};
Infer({method: 'enumerate'}, model);

